begin;
insert into public.ce_course3_resources(id,data) values
('course3_module10_pdf','{"base64": "", "sha256": "110ca0bffe92c7e613f0f3b769c33685fdd5c79b34c14bb117ab46101161aee1", "filename": "CE_HALO_Course3_Module10_Expert_Witness_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module10_questions','[{"module_id": "course_3_module_10", "question_id": "course_3_module_10_q01", "question_number": 1, "stem": "Which of the following best describes the primary purpose of CRNA expert witness testimony?", "choice_a": "To educate the trier of fact about the nurse anesthesia standard of care and how it applies to the facts of the case", "choice_b": "To advocate for the retaining attorney’s theory of the case", "choice_c": "To recommend a specific settlement value", "choice_d": "To decide whether the defendant is legally liable", "correct_choice": "a", "rationale": "Expert testimony is education, not advocacy. The CRNA expert helps the fact-finder understand the applicable standard of care; the expert does not decide the case or advocate for either side.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q02", "question_number": 2, "stem": "Which admissibility framework governs expert testimony in federal court and in most state courts today?", "choice_a": "The Health Insurance Portability and Accountability Act", "choice_b": "Daubert reliability framework under Federal Rule of Evidence 702 (as amended December 1, 2023)", "choice_c": "The AANA Code of Ethics", "choice_d": "Frye “general acceptance” test", "correct_choice": "b", "rationale": "Daubert v. Merrell Dow Pharmaceuticals (1993) and Kumho Tire (1999) established the reliability gatekeeping framework under FRE 702, which was amended effective December 1, 2023. Most state courts have adopted Daubert or a Daubert-like standard; a minority still apply Frye.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q03", "question_number": 3, "stem": "What key change did the December 1, 2023 amendment to Federal Rule of Evidence 702 make?", "choice_a": "It abolished Daubert and reinstated Frye", "choice_b": "It eliminated the requirement of a written expert report", "choice_c": "It clarified that the proponent of expert testimony must demonstrate by a preponderance of the evidence (“more likely than not”) that each admissibility requirement is met, and it emphasized that opinions must reflect a reliable application of the methodology to the facts", "choice_d": "It permitted contingency-fee arrangements for experts", "correct_choice": "c", "rationale": "The 2023 amendment clarifies the preponderance standard and adds an anti-overstatement provision in subsection (d), requiring that the opinion reflect a reliable application of the principles and methods.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q04", "question_number": 4, "stem": "A CRNA expert has been retained by defense counsel in a federal malpractice case. Which document sets out the six mandatory content elements the expert’s written report must contain?", "choice_a": "Federal Rule of Evidence 403", "choice_b": "42 CFR §482.52", "choice_c": "AANA Scope of Nurse Anesthesia Practice", "choice_d": "Federal Rule of Civil Procedure 26(a)(2)(B)", "correct_choice": "d", "rationale": "FRCP 26(a)(2)(B) sets the six required elements: opinions and bases, facts/data considered, exhibits, qualifications with 10-year publications, 4-year prior testimony list, and compensation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q05", "question_number": 5, "stem": "Which of the following is NOT one of the six required elements of a retained expert’s Rule 26(a)(2)(B) report?", "choice_a": "The retaining attorney’s trial strategy memorandum", "choice_b": "The facts or data considered", "choice_c": "A complete statement of all opinions and the basis and reasons", "choice_d": "The expert’s qualifications and publications from the past 10 years", "correct_choice": "a", "rationale": "Attorney work product and trial strategy are not disclosed in the expert’s report. The six elements are opinions/bases, facts or data considered, exhibits, qualifications with publications, prior testimony list, and compensation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q06", "question_number": 6, "stem": "Federal Rule of Evidence 703 governs which aspect of expert testimony?", "choice_a": "The right to a jury trial", "choice_b": "The bases (facts or data) on which an expert may form an opinion", "choice_c": "The judge’s authority to exclude cumulative evidence", "choice_d": "The physician’s duty to supervise CRNAs", "correct_choice": "b", "rationale": "FRE 703 addresses the facts or data an expert may rely on, including facts made known to the expert and inadmissible facts if experts in the field would reasonably rely on them.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q07", "question_number": 7, "stem": "Which statement about the CRNA expert’s duty of neutrality is most accurate?", "choice_a": "The duty of neutrality applies only when retained by the defense", "choice_b": "Neutrality is not required so long as the retaining attorney is satisfied", "choice_c": "The expert’s professional responsibility is to the truth, the evidence, and the integrity of the legal process, regardless of which side retained the expert", "choice_d": "Neutrality is optional in state-court proceedings", "correct_choice": "c", "rationale": "Neutrality is a core professional obligation regardless of retaining side. The AANA Code of Ethics and the expert’s duty to the tribunal both require honest, impartial opinion based on the evidence.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q08", "question_number": 8, "stem": "Which of the following fee arrangements is prohibited for a CRNA expert witness under the AANA Code of Ethics and generally under professional ethics rules?", "choice_a": "Hourly billing for record review, deposition preparation, and trial time", "choice_b": "Separate rates for deposition versus trial testimony", "choice_c": "An advance retainer that is applied to initial hours of review", "choice_d": "A contingency fee that depends on the outcome or settlement value of the case", "correct_choice": "d", "rationale": "Contingency fees create a conflict of interest and are prohibited. Expert compensation must be based on time and expertise, not on the outcome of the case.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q09", "question_number": 9, "stem": "A CRNA expert retained by plaintiff’s counsel discovers that the anesthesia record actually documents timely recognition and appropriate treatment of the patient’s hypotensive episode, contrary to the plaintiff’s theory. What is the ethically correct action?", "choice_a": "Report the actual findings honestly to retaining counsel and be prepared to acknowledge them; withdraw if asked to shape opinions contrary to the record", "choice_b": "Change the opinion to support the plaintiff’s theory because that party is paying", "choice_c": "Notify opposing counsel directly", "choice_d": "Refuse to write a report but keep the retainer", "correct_choice": "a", "rationale": "Neutrality and honesty are non-negotiable. The expert must report actual findings to retaining counsel; if pressured to distort opinions, the expert should decline or withdraw. Ex parte contact with opposing counsel is improper.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q10", "question_number": 10, "stem": "Which of the following best distinguishes deposition testimony from trial testimony?", "choice_a": "Deposition testimony is not under oath", "choice_b": "Deposition is out-of-court, pre-trial testimony taken under oath for discovery, preservation, and impeachment purposes, typically without a judge present in real time; trial testimony is given in open court before the fact-finder with the judge ruling on objections in real time", "choice_c": "Only trial testimony can be used at trial", "choice_d": "Cross-examination is only permitted at deposition", "correct_choice": "b", "rationale": "Depositions and trial are both under oath, but depositions occur out of court for discovery/preservation/impeachment. At trial the judge is present to rule on objections and the fact-finder hears the testimony directly.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q11", "question_number": 11, "stem": "Which qualification factor is often most decisive when a court evaluates whether a CRNA expert is qualified to testify in a specific case?", "choice_a": "Whether the expert has published a bestseller", "choice_b": "The expert’s undergraduate GPA", "choice_c": "Substantially similar clinical experience relevant to the specific practice area at issue (e.g., obstetric, regional, pediatric, office-based)", "choice_d": "Number of years the expert has held any CRNA license", "correct_choice": "c", "rationale": "Clinical relevance and substantial similarity of experience are decisive under FRE 702 and most state analogs. Generic CRNA experience without substantial similarity to the case may not qualify the expert.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q12", "question_number": 12, "stem": "Under Federal Rule of Civil Procedure 26(a)(2)(B), the expert’s report must include a list of prior testimony from what look-back period?", "choice_a": "Lifetime", "choice_b": "The past 1 year", "choice_c": "The past 10 years", "choice_d": "The past 4 years", "correct_choice": "d", "rationale": "Rule 26(a)(2)(B)(v) requires disclosure of all cases in which the expert testified at trial or by deposition in the previous 4 years. Publications require a 10-year look-back.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q13", "question_number": 13, "stem": "A CRNA expert is asked at deposition whether care by the surgeon fell below the surgical standard of care. What is the appropriate response?", "choice_a": "Decline to opine on the surgical standard of care because it is outside the CRNA’s scope of expertise, unless the CRNA is independently qualified to render such an opinion", "choice_b": "Offer an opinion because the CRNA works with surgeons daily", "choice_c": "Refuse to answer any question about the surgeon", "choice_d": "Ask the surgeon’s attorney for guidance", "correct_choice": "a", "rationale": "A CRNA expert should stay within the boundaries of nurse anesthesia expertise. Testifying about a surgical standard of care exceeds scope unless the CRNA is separately qualified in that area.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q14", "question_number": 14, "stem": "Which of the following most accurately describes the Frye standard?", "choice_a": "Expert testimony is always admissible if the witness holds a professional license", "choice_b": "Expert testimony is admissible only if the underlying scientific technique has gained general acceptance in the relevant scientific community", "choice_c": "Fee agreements must be filed with the court", "choice_d": "The judge acts as a gatekeeper under a preponderance standard", "correct_choice": "b", "rationale": "Frye v. United States (D.C. Cir. 1923) requires “general acceptance” in the relevant field. Daubert/FRE 702 superseded Frye in federal court; a minority of state courts still apply Frye.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q15", "question_number": 15, "stem": "The CRNA expert should analyze causation:", "choice_a": "Together with breach, treating them as one question", "choice_b": "Only when retained by defense counsel", "choice_c": "Separately from breach — a breach of the standard does not automatically establish causation of the alleged injury, and the expert should evaluate patient factors, surgical event, medication response, equipment, system failure, and other provider conduct", "choice_d": "Only in criminal cases", "correct_choice": "c", "rationale": "Breach and causation are legally and analytically distinct. A careful expert opinion identifies the mechanism linking any breach to harm and acknowledges when causation cannot be established.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q16", "question_number": 16, "stem": "Which of the following is a fact-witness role rather than a retained-expert role?", "choice_a": "Testifying about opinions on the standard of care after reviewing an anesthesia record for the first time as a paid consultant", "choice_b": "Explaining causation based on peer-reviewed literature not involved in the underlying care", "choice_c": "Providing a Rule 26(a)(2)(B) written report", "choice_d": "Describing what the CRNA personally observed, said, did, and documented while caring for the patient at issue", "correct_choice": "d", "rationale": "A fact witness testifies from personal knowledge about events he or she observed. A retained expert offers opinions based on specialized knowledge applied to facts not personally observed.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q17", "question_number": 17, "stem": "Which of the following describes a compliant CRNA expert fee structure?", "choice_a": "Written, activity-based hourly rates (screening, review, report, deposition preparation, deposition, trial preparation, trial, travel, cancellation) that are the same regardless of retaining side and not contingent on outcome", "choice_b": "A flat fee payable only if the plaintiff wins", "choice_c": "Different rates depending on which side retained the expert", "choice_d": "A percentage of any damages awarded", "correct_choice": "a", "rationale": "Ethical, defensible fee structures are written, activity-based, time-and-expertise-driven, applied uniformly regardless of retaining side, and never contingent on outcome.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q18", "question_number": 18, "stem": "Under amended FRE 702(d), the expert’s opinion must:", "choice_a": "Be pre-approved by the retaining attorney", "choice_b": "Reflect a reliable application of the principles and methods to the facts of the case — in other words, the opinion must stay within the bounds of what the methodology reliably supports (no overstatement)", "choice_c": "Cite at least three peer-reviewed articles", "choice_d": "Be endorsed by the state licensing board", "correct_choice": "b", "rationale": "The 2023 amendment to Rule 702(d) is an anti-overstatement provision requiring that the opinion reflect a reliable application of the methodology to the facts. Opinions that outrun their basis may be excluded.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q19", "question_number": 19, "stem": "A CRNA expert practicing exclusively in adult cardiac anesthesia is contacted about a case involving neonatal airway management. The most appropriate initial action is to:", "choice_a": "Accept the case and study the topic before the deposition", "choice_b": "Accept but disclaim any opinion in the written report", "choice_c": "Screen for clinical relevance and, if the case is outside the expert’s substantially similar experience, decline the engagement", "choice_d": "Accept and rely entirely on the retaining attorney’s summary", "correct_choice": "c", "rationale": "Clinical competence and substantial similarity are threshold ethical and legal requirements. Cases outside the expert’s scope should be declined.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q20", "question_number": 20, "stem": "Kumho Tire Co. v. Carmichael (1999) extended the Daubert gatekeeping obligation to:", "choice_a": "Only scientific expert testimony", "choice_b": "Only cases involving product defects", "choice_c": "Only criminal cases", "choice_d": "All expert testimony, including experience-based clinical testimony — which describes most CRNA expert opinion", "correct_choice": "d", "rationale": "Kumho Tire extended Daubert reliability gatekeeping to all expert testimony, including specialized experience-based opinion typical of nurse anesthesia expert work.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q21", "question_number": 21, "stem": "On cross-examination, opposing counsel asks the CRNA expert about total fees billed in the case and about prior cases the expert has reviewed for the retaining law firm. The most appropriate response is:", "choice_a": "Answer honestly and accurately, because transparent, consistent, reasonable billing practices support the appearance and reality of neutrality and the expert should be comfortable explaining fees under oath", "choice_b": "Give an intentionally vague answer to protect the retaining firm", "choice_c": "Refuse to answer questions about fees", "choice_d": "Ask the judge to seal the fee testimony", "correct_choice": "a", "rationale": "Fees, billing history, and prior engagements are proper subjects of cross-examination. Honest, consistent answers preserve credibility.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q22", "question_number": 22, "stem": "Which of the following is the best approach to identifying the applicable standard of care in a CRNA case?", "choice_a": "Ask the retaining attorney what standard applies", "choice_b": "Consider multiple sources including AANA Standards for Nurse Anesthesia Practice, the 2026 Scope of Nurse Anesthesia Practice, current peer-reviewed literature, evidence-based specialty guidelines, state nurse practice acts, facility policies, and the realities of the practice setting", "choice_c": "Rely exclusively on personal opinion", "choice_d": "Cite one single clinical guideline as automatically dispositive", "correct_choice": "b", "rationale": "Standards of care are drawn from multiple sources and applied to the total clinical context. No single source is automatically dispositive.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q23", "question_number": 23, "stem": "A CRNA expert is preparing for deposition. Which preparation practice is most likely to preserve credibility?", "choice_a": "Memorizing scripted answers provided by the retaining attorney", "choice_b": "Avoiding review of the record so answers appear “fresh”", "choice_c": "Reviewing the expert’s own written report and any prior publications and testimony relevant to the case", "choice_d": "Reading the plaintiff’s expert report only", "correct_choice": "c", "rationale": "Effective preparation includes rereading one’s own report, prior publications, and prior testimony to ensure consistency and to anticipate cross-examination.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q24", "question_number": 24, "stem": "Which statement about hindsight bias is correct?", "choice_a": "Adverse outcomes automatically prove substandard care", "choice_b": "Good outcomes prove that care met the standard", "choice_c": "Hindsight is required in expert analysis", "choice_d": "A CRNA expert should evaluate care prospectively, based on what was reasonably knowable at the time care was provided, rather than retrospectively based on the outcome", "correct_choice": "d", "rationale": "Prospective evaluation — what a reasonably prudent CRNA would have known and done at the time — is the correct standard. A poor outcome does not by itself establish a breach; a good outcome does not by itself establish adequate care.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_10", "question_id": "course_3_module_10_q25", "question_number": 25, "stem": "Which of the following is the most accurate description of the CRNA expert’s scope of permissible testimony?", "choice_a": "The expert may testify about matters within actual education, certification, training, and clinical experience — for example, anesthesia assessment, plan, induction, maintenance, airway, monitoring, pharmacologic decisions, emergence, post-anesthesia care, documentation, professional standards, and CRNA scope — but should avoid legal conclusions, speculation about intent, or unrelated specialty opinions unless independently qualified", "choice_b": "The expert may render legal conclusions if the retaining attorney requests them", "choice_c": "The expert may testify only about the CRNA’s birthplace and training", "choice_d": "The expert may testify about any medical or nursing topic once sworn", "correct_choice": "a", "rationale": "Testimony must remain within the expert’s actual qualifications. Legal conclusions and opinions outside nurse anesthesia expertise are inappropriate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module10_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;